USE [QuattroCafe];
GO

BEGIN TRANSACTION;

MERGE [QuattroCafe].[dbo].[Products] AS target
USING (
    SELECT
        CASE
            WHEN raw.ProductName IS NULL THEN NULL
            ELSE LEFT(raw.ProductName, COALESCE(lengths.ProductNameMax, LEN(raw.ProductName)))
        END AS ProductName,
        raw.CategoryId,
        CASE
            WHEN raw.Description IS NULL THEN NULL
            ELSE LEFT(raw.Description, COALESCE(lengths.DescriptionMax, LEN(raw.Description)))
        END AS Description,
        CASE
            WHEN raw.Tooltip IS NULL THEN NULL
            ELSE LEFT(raw.Tooltip, COALESCE(lengths.TooltipMax, LEN(raw.Tooltip)))
        END AS Tooltip,
        raw.Price,
        CASE
