    (N'Double Türk Kahvesi', 21, N'Daha yoğun lezzet isteyenler için double Türk kahvesi.', N'Yeni', 160, N'double-türk-kahvesi-sıcakiçecekler.jpg', 0),
    (N'Osmanlı Kahvesi', 21, N'Daha yoğun lezzet isteyenler için double Türk kahvesi.', N'Yeni', 120, N'osmanlı-kahvesi-sıcakiçecek.jpg', 0),
    (N'Menengiç Kahvesi', 21, N'Daha yoğun lezzet isteyenler için double Türk kahvesi.', N'Yeni', 120, N'menengiç-kahvesi-sıcakiçecek.jpg', 0),
    (N'Bonfrit', 16, N'Kızarmış baharatlı parmak patatesler, dip sos ile servis edilir.', N'Yeni', 180, N'patates-atıştırmalık.jpg', 0),
    (N'Çıtır Tavuk', 16, N'Kızarmış paneli çıtır tavuk parçaları, patates cips ve dip sos ile servis edilir.', N'Yeni', 330, N'çıtır-tavuk-atıştırmalık.jpg', 0),
    (N'Karışık Sepet', 16, N'Sigara böreği, sosis, soğan halkası, çıtır tavuk, patates cips ve dip sos ile servis edilir.', N'Yeni', 390, N'karışık-sepet-atıştırmalık.jpg', 0),
    (N'Sigara Böreği', 16, N'Kızarmış sigara börekleri, patates cips ve dip sos ile servis edilir.', N'Yeni', 220, N'sigara-böreği-atıştırmalık.jpg', 0),
    (N'Soğan Halkası', 16, N'Panelenmiş çıtır soğan, patates cips ve dip sos ile servis edilir.', N'Yeni', 220, N'soğan-halkası-atıştırmalık.jpg', 0)
    ) AS raw (ProductName, CategoryId, Description, Tooltip, Price, Image, IsFeatured)
    CROSS JOIN (
        SELECT
            MAX(CASE WHEN c.name = N'ProductName' THEN CASE WHEN t.name IN (N'nchar', N'nvarchar') AND c.max_length <> -1 THEN c.max_length / 2 WHEN c.max_length = -1 THEN 4000 ELSE c.max_length END END) AS ProductNameMax,
            MAX(CASE WHEN c.name = N'Description' THEN CASE WHEN t.name IN (N'nchar', N'nvarchar') AND c.max_length <> -1 THEN c.max_length / 2 WHEN c.max_length = -1 THEN 4000 ELSE c.max_length END END) AS DescriptionMax,
            MAX(CASE WHEN c.name = N'Tooltip' THEN CASE WHEN t.name IN (N'nchar', N'nvarchar') AND c.max_length <> -1 THEN c.max_length / 2 WHEN c.max_length = -1 THEN 4000 ELSE c.max_length END END) AS TooltipMax,
            MAX(CASE WHEN c.name = N'Image' THEN CASE WHEN t.name IN (N'nchar', N'nvarchar') AND c.max_length <> -1 THEN c.max_length / 2 WHEN c.max_length = -1 THEN 4000 ELSE c.max_length END END) AS ImageMax
        FROM sys.columns AS c
        INNER JOIN sys.types AS t
            ON c.user_type_id = t.user_type_id
        WHERE c.object_id = OBJECT_ID(N'dbo.Products')
    ) AS lengths
) AS source
ON target.ProductName = source.ProductName AND target.CategoryId = source.CategoryId
WHEN MATCHED AND (
    ISNULL(target.Description, N'') <> ISNULL(source.Description, N'')
    OR ISNULL(target.Tooltip, N'') <> ISNULL(source.Tooltip, N'')
    OR target.Price <> source.Price
    OR ISNULL(target.Image, N'') <> ISNULL(source.Image, N'')
    OR ISNULL(target.IsFeatured, 0) <> source.IsFeatured
) THEN UPDATE SET
    target.Description = source.Description,
    target.Tooltip = source.Tooltip,
    target.Price = source.Price,
    target.Image = source.Image,
    target.IsFeatured = source.IsFeatured
WHEN NOT MATCHED BY TARGET THEN
    INSERT (ProductName, CategoryId, Description, Tooltip, Price, Image, IsFeatured)
    VALUES (source.ProductName, source.CategoryId, source.Description, source.Tooltip, source.Price, source.Image, source.IsFeatured);

COMMIT TRANSACTION;

